def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Sort intervals by start point
    a = sorted(a)
    b = sorted(b)

    # Merge overlapping intervals in b
    merged_b = []
    for start, end in b:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    result = []

    for a_start, a_end in a:
        current_start = a_start

        # Subtract all b intervals that overlap with [current_start, a_end)
        for b_start, b_end in merged_b:
            # If b interval is completely before current interval, skip
            if b_end <= current_start:
                continue

            # If b interval is completely after current interval, we're done
            if b_start >= a_end:
                break

            # If there's a gap before b_start, add it to result
            if current_start < b_start:
                result.append([current_start, b_start])

            # Move current_start past this b interval
            current_start = max(current_start, b_end)

        # Add remaining part of a interval if any
        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge touching/overlapping intervals in result
    if not result:
        return []

    merged_result = [result[0]]
    for start, end in result[1:]:
        if start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

